def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_nth_prime(n):
    primes = []
    num = 1
    while len(primes) < n:
        num += 1
        if is_prime(num):
            primes.append(num)
    return primes[n-1]

